    from collections import Counter
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    rays=[]
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v==bg: continue
            for dr,dc in ((1,1),(1,-1)):
                rr,cc=r+dr,c+dc
                if 0<=rr<h and 0<=cc<w and g[rr][cc]==v:
                    rays.extend(((r,c,-dr,-dc,v),(rr,cc,dr,dc,v)))
    for r,c,dr,dc,v in rays:
        rr,cc=r+dr,c+dc
        while 0<=rr<h and 0<=cc<w and g[rr][cc]==bg:
            g[rr][cc]=v
            rr+=dr;cc+=dc
    return g

