    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                cc = c + dc
                if 0 <= cc < w and grid[r + 1][cc] == color:
                    seeds.append((r + 1, cc, 1, dc, color))
    for r, c, dr, dc, color in seeds:
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
            out[rr][cc] = color
            rr += dr
            cc += dc
    return out

